<?php
require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/shu_pinjaman_helper.php';
if(!shuPinjamanSiap($db)){http_response_code(404);exit('Rincian SHU tidak ditemukan.');}
$s=$db->prepare('SELECT h.*,p.kode_pinjaman,a.nama_lengkap,a.kode_anggota FROM shu_hak_pinjaman h JOIN pinjaman p ON p.id=h.pinjaman_id JOIN anggota a ON a.id=h.anggota_id WHERE h.id=? AND a.user_id=?');$s->execute([(int)($_GET['id']??0),$_SESSION['user_id']]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!$r){http_response_code(404);exit('Rincian SHU tidak ditemukan.');}
require_once __DIR__.'/../tcpdf/tcpdf.php';$pdf=new TCPDF('P','mm','A4',true,'UTF-8',false);$pdf->setPrintHeader(false);$pdf->SetTitle('Rincian SHU '.$r['kode_pinjaman']);$pdf->AddPage();$pdf->SetFont('dejavusans','',11);$org=$db->query('SELECT nama FROM koperasi WHERE id=1')->fetchColumn();$html='<h2>'.layananEscape($org).'</h2><h3>Rincian hak SHU pinjaman</h3><p>'.layananEscape($r['nama_lengkap'].' / '.$r['kode_anggota']).'</p><table border="1" cellpadding="7"><tr><td>Pinjaman</td><td>'.layananEscape($r['kode_pinjaman']).'</td></tr><tr><td>Jenis</td><td>'.($r['jenis']==='referensi'?'Bonus referensi':'Pelunasan pribadi').'</td></tr><tr><td>Dasar</td><td>'.formatRupiah($r['dasar_pinjaman']).' × '.$r['persen'].'%</td></tr><tr><th>Hak SHU</th><th>'.formatRupiah($r['jumlah']).'</th></tr><tr><td>Status</td><td>'.($r['status_bayar']==='sudah'?'Sudah dibayar':'Belum dibayar').'</td></tr></table>';$pdf->writeHTML($html);$pdf->Output('Rincian-SHU-'.$r['kode_pinjaman'].'.pdf','D');exit;
